// ============================================================================
// CLASSIFICAR D1 — traduz as fontes fiscais em categorias (nunca em pontos).
//
// MUDANCA DE ARQUITETURA (2026-08):
// Este fluxo roda ANTES do enriquecimento cadastral, porque e ele que descobre
// e CONFIRMA o CNPJ da matriz (via retorno da Infosimples, incluindo o retry do
// erro 620). O Orquestrador usa esse cnpj_matriz para consultar o Econodata,
// o QSA e os vinculos societarios na matriz.
//
// Por isso o t_pgfn NAO e mais decidido aqui: a existencia da divida ativa vem
// do Econodata da matriz, que so e consultado depois deste fluxo. O que este
// fluxo entrega sobre o PGFN e a MATERIA-PRIMA da certidao:
//   cnd_emitida, cnd_tipo, cnd_debitos_pgfn
// e o node 'Consolidar PGFN + Gate G3' do Orquestrador fecha a classificacao
// e avalia o Gate G3.
// ============================================================================

const cndOriginal = $('Infosimples · CND Federal (Resultado Final)').first().json;
const cnd = cndOriginal.data?.[0] ?? null;   // null = a Infosimples nao emitiu a certidao
const est = $('Direct Data · CND Estadual').first().json.retorno ?? null;

// Sintonia: 'A+' pode vir do Selo Sintonia OU da lista do Confia (fallback).
const sintoniaCls = $('Classificar Sintonia').first().json ?? {};
const t_sintonia = sintoniaCls.t_sintonia ?? 'ND';
const sintonia_fonte = sintoniaCls.sintonia_fonte ?? 'nenhum';
const confia_lista_origem = sintoniaCls.confia_lista_origem ?? 'nao_consultada';

const norm = $('Normalizar CNPJ Matriz').first().json;

// ---------------------------------------------------------------------------
// CNPJ da matriz CONFIRMADO — este e o principal produto novo do D1.
// Ordem de confianca:
//   1) cnpj devolvido pelo erro 620 da Infosimples (matriz de fato)
//   2) raiz + 0001 + DV calculado (cobre a imensa maioria dos casos)
// ---------------------------------------------------------------------------
let cnpj_matriz = norm.cnpj_matriz;
let matriz_fonte = 'calculado_0001';
let retry_matriz_real = false;
try {
  const real = $('Extrair CNPJ Matriz Real do Erro').first().json.cnpj_matriz_real;
  retry_matriz_real = true;
  if (real) { cnpj_matriz = real; matriz_fonte = 'confirmado_api_620'; }
} catch (e) { /* nao houve retry — segue com o calculado */ }

const cnpj_original = norm.cnpj_original;
const eh_filial = cnpj_matriz !== cnpj_original;

// ---------------------------------------------------------------------------
// t_cnd — categoria da certidao federal. 'ND' quando a Infosimples nao emitiu.
// ---------------------------------------------------------------------------
const tipo = cnd?.tipo || '';
let t_cnd = 'ND';
if (cnd) {
  if (tipo.includes('efeitos de negativa')) t_cnd = 'Positiva c/ efeitos de negativa';
  else if (tipo === 'Positiva') t_cnd = 'Positiva';   // debito exigivel, sem regularizacao
  else if (tipo === 'Negativa') t_cnd = 'Negativa';   // nada em aberto
}

// ---------------------------------------------------------------------------
// CND Estadual (Direct Data) — do ESTABELECIMENTO consultado (filial), com a UF
// dele. Independente do federal.
// ---------------------------------------------------------------------------
let t_est = 'ND';
if (est) {
  t_est = (!est.possuiDebito || est.efeitoNegativa) ? 'Regular' : 'Irregular';
}

return [{
  json: {
    // ---- identificacao da matriz (consumido pelo Orquestrador) -------------
    cnpj_matriz,
    cnpj_consultado: cnpj_original,
    eh_filial,
    matriz_fonte,          // calculado_0001 | confirmado_api_620
    retry_matriz_real,

    // ---- contrato de classificacao ----------------------------------------
    t_cnd,
    t_est,
    t_sintonia,
    sintonia_fonte,        // selo_sintonia | confia_protocolo | nenhum
    confia_lista_origem,   // site | site+snapshot | snapshot_local | nao_consultada

    // ---- materia-prima do PGFN (o Orquestrador fecha a classificacao) -----
    cnd_emitida: !!cnd,
    cnd_tipo: tipo || null,
    cnd_debitos_pgfn: cnd ? (cnd.debitos_pgfn === true) : null,

    // ---- gate ------------------------------------------------------------
    // O Gate G3 (CND positiva + PGFN irregular) depende da divida do Econodata
    // da matriz, entao e avaliado no Orquestrador. Mantido aqui como null para
    // preservar o contrato caso algum gate exclusivamente fiscal seja criado.
    gate_disparado: null,

    // ---- auditoria --------------------------------------------------------
    cnd_code: cndOriginal?.code ?? null,
    cnd_erro: (!cnd && Array.isArray(cndOriginal?.errors) && cndOriginal.errors.length) ? String(cndOriginal.errors[0]) : null,
  }
}];

// Normaliza o CNPJ para a MATRIZ (raiz + 0001 + DV recalculado).
// Motivo: a CND Federal (RFB/PGFN) so e emitida para o CNPJ da matriz.
// Chamar com o CNPJ de uma filial retorna code 620:
//   "A certidao deve ser emitida para o CNPJ da matriz - 10.483.444/0001-89"
// A certidao da matriz abrange todos os estabelecimentos (filiais), entao
// o resultado e valido para o fornecedor consultado.
//
// Suporta o CNPJ alfanumerico (regra oficial: valor do caractere = ASCII - 48).

const raw = String($json.cnpj || '')
  .toUpperCase()
  .replace(/[^0-9A-Z]/g, '')
  .padStart(14, '0');

const raiz = raw.substring(0, 8);
const base = raiz + '0001';

const val = (c) => c.charCodeAt(0) - 48;
const calcDV = (str, pesos) => {
  const soma = str.split('').reduce((acc, c, i) => acc + val(c) * pesos[i], 0);
  const resto = soma % 11;
  return resto < 2 ? 0 : 11 - resto;
};

const d1 = calcDV(base, [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]);
const d2 = calcDV(base + d1, [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]);

const cnpj_matriz = `${base}${d1}${d2}`;
